{
  "justification": "Salience clusters around material well-being and public health (care and proportionality), with immigration/national identity (loyalty) also highly prominent, and secondary weight on institutional order (authority) and distributive fairness (equality). Because the instrument records issues raised but not direction, the weights reflect relative prominence of domains rather than which side of each debate respondents support.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Mental health/Well-being; Coronavirus/Pandemic diseases; Pollution/Environment/Climate change (harm framing)",
      "weight": 0.26
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Inflation/Prices; Taxation; Unemployment/Factory closure/Lack of industry; Public services in general; Nationalisation/Privatisation (economic performance)",
      "weight": 0.24
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration/Immigrants; Common Market/Brexit/EU/Europe; Defence/Foreign affairs/International terrorism (ingroup protection); UK union/Devolution/Reform; Northern Ireland; Race relations (social cohesion)",
      "weight": 0.18
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Housing; Education/Schools; Low pay/Minimum wage/Fair wages; Pensions/Social security/Benefits",
      "weight": 0.16
    },
    {
      "foundation": "authority",
      "basis": "Defence/Foreign affairs/International terrorism; Crime/Law and order/Violence/Vandalism; Lack of faith in politics/politicians/government; Local government/Council tax; Morality/Individual behaviour/Lifestyle (norms)",
      "weight": 0.10
    },
    {
      "foundation": "sanctity",
      "basis": "Pollution/Environment/Climate change (purity of nature); Morality/Individual behaviour/Lifestyle; Drug abuse; Coronavirus/Pandemic diseases (pathogen avoidance); Food production/Farming; Nuclear weapons/Disarmament; Population levels/Overpopulation",
      "weight": 0.06
    }
  ]
}
